revision.text:
/* Template:Directory card/styles.css: the picture cards on the directory pages,
   matching the directory buttons on the front page (TemplateStyles). */
.rp-dcards {
	display: grid;
	grid-template-columns: repeat( auto-fill, minmax( 210px, 1fr ) );
	gap: 10px;
	margin: 0.6em 0 1.4em;
}
.rp-dcard {
	position: relative;
	display: flex;
	align-items: center;
	min-height: 52px;
	padding: 10px 16px;
	overflow: hidden;
	border: 1px solid rgba( 127, 127, 127, 0.28 );
	border-radius: 8px;
	background: rgba( 127, 127, 127, 0.07 );
	transition: border-color 0.15s, transform 0.15s;
}
.rp-dcard:hover {
	border-color: rgba( 127, 127, 127, 0.55 );
	transform: translateY( -2px );
}
/* With a picture: the art sits on the right, over a dark fade from the left */
.rp-dcard--image {
	border-color: transparent;
	background: linear-gradient( to right, #000 0%, rgba( 0, 0, 0, 0.85 ) 35%, rgba( 0, 0, 0, 0.35 ) 100% );
}
.rp-dcard--image:hover {
	border-color: rgba( 255, 255, 255, 0.25 );
}
.rp-dcard-bg {
	position: absolute;
	inset: 0;
}
.rp-dcard-bg span,
.rp-dcard-bg a {
	display: block;
	width: 100%;
	height: 100%;
}
.rp-dcard-bg img {
	display: block;
	width: 100%;
	height: 100%;
	max-width: none;
	object-fit: cover;
	object-position: right center;
}
.rp-dcard--image::after {
	content: '';
	position: absolute;
	inset: 0;
	z-index: 1;
	background: linear-gradient( to right, rgba( 0, 0, 0, 0.9 ) 0%, rgba( 0, 0, 0, 0.5 ) 35%, rgba( 0, 0, 0, 0 ) 65% );
}
.rp-dcard-text {
	position: relative;
	z-index: 2;
	flex: 1;
	align-self: stretch;
	display: flex;
	flex-direction: column;
	justify-content: center;
	min-width: 0;
	/* fill the whole card, so the stretched link below covers all of it */
	margin: -10px -16px;
	padding: 10px 16px;
}
.rp-dcard--image .rp-dcard-text {
	text-shadow: 0 1px 3px rgba( 0, 0, 0, 0.7 );
}
.rp-dcard-label {
	font-weight: 600;
}
.rp-dcard-label a,
.rp-dcard-label a:visited {
	color: inherit;
}
.rp-dcard--image .rp-dcard-label a,
.rp-dcard--image .rp-dcard-count {
	color: #fff;
}
/* The whole card is clickable: the label's link stretches over it */
.rp-dcard-label a::after {
	content: '';
	position: absolute;
	inset: 0;
}
.rp-dcard-count {
	margin-top: 2px;
	font-size: 0.8125rem;
	opacity: 0.8;
}

/* "Add a page" box and the tables */
.rp-dir-add {
	margin: 0.4em 0 1.4em;
	padding: 12px 16px;
	border: 1px solid rgba( 127, 127, 127, 0.28 );
	border-radius: 8px;
	background: rgba( 127, 127, 127, 0.07 );
}
.rp-dir-add .mw-inputbox-centered {
	margin: 0;
}
.rp-dir-add form {
	display: flex;
	flex-wrap: wrap;
	justify-content: flex-start !important;
	gap: 8px;
}
.rp-dir-add .cdx-text-input {
	flex: 0 1 280px;
	min-width: 0;
}
.rp-dir-table table {
	width: 100%;
}
